function ScrollReset() {
  const loc = useLocation();
  useEffect(() => {
    const el = document.querySelector('[data-screen-scroll]') as HTMLElement | null;
    if (el) el.scrollTo(0, 0);
  }, [loc.pathname]);
  return null;
}

function ShellLayout() {
  const loc = useLocation();
  const isTabPage = /^\/(home|card|wealth|me)\/?$/.test(loc.pathname) || loc.pathname === "/";
  return (
    <div className="relative h-full w-full bg-surface-base">
      <StatusBar />
      {isTabPage && <TopBar />}
      <main data-screen-scroll className={`absolute inset-x-0 bottom-0 ${isTabPage ? "top-[96px]" : "top-[44px]"} overflow-y-auto overflow-x-hidden no-scrollbar`}>
        <Routes>
          <Route path="/" element={<HomeScreen />} />
          <Route path="/home" element={<HomeScreen />} />
          <Route path="/account/:ccy" element={<AccountDetailScreen />} />
          <Route path="/tx" element={<TxListScreen />} />
          <Route path="/tx/:id" element={<TxDetailScreen />} />
          <Route path="/notifications" element={<NotificationsScreen />} />

          <Route path="/card" element={<CardScreen />} />
          <Route path="/card/tx" element={<CardTxListScreen />} />
          <Route path="/card/topup" element={<CardTopupScreen />} />
          <Route path="/card/withdraw" element={<CardWithdrawScreen />} />
          <Route path="/card/limits" element={<CardLimitsScreen />} />
          <Route path="/card/pin" element={<CardPinResetScreen />} />
          <Route path="/card/cvv" element={<CardCvvScreen />} />

          <Route path="/wealth" element={<WealthScreen />} />
          <Route path="/wealth/product/:id" element={<ProductDetailScreen />} />
          <Route path="/wealth/holdings" element={<HoldingsScreen />} />
          <Route path="/wealth/holding/:id" element={<HoldingDetailScreen />} />
          <Route path="/wealth/buy/:id" element={<PurchaseAmountScreen />} />
          <Route path="/wealth/buy/:id/confirm" element={<PurchaseConfirmScreen />} />

          <Route path="/me" element={<MeScreen />} />
          <Route path="/me/security" element={<SecurityCenterScreen />} />
          <Route path="/me/payment-pwd" element={<ChangePaymentPwdScreen />} />
          <Route path="/me/identity" element={<IdentityScreen />} />
          <Route path="/me/language" element={<LanguageScreen />} />
          <Route path="/me/theme" element={<ThemeScreen />} />
          <Route path="/me/about" element={<AboutScreen />} />
          <Route path="/me/customer" element={<CustomerServiceScreen />} />

          <Route path="/topup" element={<TopupHubScreen />} />
          <Route path="/topup/swift" element={<SwiftDetailsScreen />} />
          <Route path="/topup/usdt" element={<UsdtAddressScreen />} />
          <Route path="/topup/cny" element={<CnyAmountScreen />} />

          <Route path="/exchange" element={<ExchangeScreen />} />
          <Route path="/exchange/confirm" element={<ExchangeConfirmScreen />} />

          <Route path="/remit" element={<RemitPayeeScreen />} />
          <Route path="/remit/payees" element={<PayeeListScreen />} />
          <Route path="/remit/:payeeId/amount" element={<RemitAmountScreen />} />
          <Route path="/remit/:payeeId/preview" element={<RemitPreviewScreen />} />
          <Route path="/remit/:payeeId/pay" element={<RemitPasswordScreen />} />
          <Route path="/remit/:payeeId/timeline" element={<RemitTimelineScreen />} />

          <Route path="/payout" element={<PayoutHubScreen />} />
          <Route path="/payout/usdt" element={<PayoutUsdtScreen />} />
          <Route path="/payout/cny" element={<PayoutCnyScreen />} />

          <Route path="/login" element={<LoginScreen />} />
          <Route path="/verify" element={<VerifyCodeScreen />} />
          <Route path="/pin-setup" element={<PinSetupScreen />} />

          <Route path="/protection" element={<GlobalProtectionScreen />} />
          <Route path="*" element={<HomeScreen />} />
        </Routes>
        <ScrollReset />
      </main>
      {isTabPage && <TabBar />}
    </div>
  );
}

export default function App() {
  return (
    <ToastProvider>
      <PhoneCanvas>
        <ShellLayout />
      </PhoneCanvas>
    </ToastProvider>
  );
}


