export type Currency = "CNY" | "CNH" | "USD" | "HKD" | "USDT" | "USDC";

export interface Wallet {
  ccy: Currency;
  name: string;
  balance: number;
  convertedCNH: number;
  hint?: string;
  locked?: boolean;
}

export type TxType = "transfer-in" | "transfer-out" | "exchange" | "card-spend" | "card-topup" | "card-withdraw" | "wealth-buy" | "wealth-redeem" | "wealth-interest";
export type TxStatus = "completed" | "processing" | "pending" | "failed" | "frozen";

export interface Transaction {
  id: string;
  date: string;
  type: TxType;
  status: TxStatus;
  ccy: Currency;
  amount: number;
  counterparty?: string;
  network?: string;
  hash?: string;
  merchant?: string;
  channel?: string;
  note?: string;
  feeCcy?: Currency;
  fee?: number;
}

export type PayeeType = "swift" | "wallet" | "crypto";

export interface PayeeBase {
  id: string;
  type: PayeeType;
  nickname: string;
  lastUsed?: string;
}
export interface PayeeSwift extends PayeeBase {
  type: "swift";
  beneficiary: string;
  bank: string;
  swift: string;
  account: string;
  country: string;
  city?: string;
  bankAddress?: string;
}
export interface PayeeWallet extends PayeeBase {
  type: "wallet";
  provider: "Alipay" | "WeChat" | "Wise" | "PayPal";
  account: string;
  realName: string;
}
export interface PayeeCrypto extends PayeeBase {
  type: "crypto";
  network: "BSC" | "Arbitrum" | "Base" | "ERC20";
  address: string;
  asset: "USDT" | "USDC";
}
export type Payee = PayeeSwift | PayeeWallet | PayeeCrypto;

export interface CardInfo {
  number: string;
  holder: string;
  expiry: string;
  cvv: string;
  balance: number;
  ccy: Currency;
  status: "normal" | "freezing" | "frozen" | "unfreezing";
  kind: "physical" | "virtual";
  monthSpend: number;
  monthLimit: number;
}

export interface Notification {
  id: string;
  category: "system" | "trade" | "wealth";
  title: string;
  body: string;
  time: string;
  read: boolean;
  highlight?: boolean;
}

export interface InvestProduct {
  id: string;
  name: string;
  ccy: Currency;
  apy: number;
  apyHigh?: number;
  type: "stable" | "fund" | "quant" | "daily";
  term: string;
  minBuy: number;
  riskLevel: 1 | 2 | 3 | 4 | 5;
  tag?: string;
  description?: string;
  manager?: string;
}

export interface InvestHolding {
  id: string;
  productId: string;
  productName: string;
  ccy: Currency;
  principal: number;
  earned: number;
  apy: number;
  startDate: string;
  endDate?: string;
  type: "stable" | "fund" | "quant" | "daily";
}

