import { clsx, type ClassValue } from "clsx";

export function cn(...inputs: ClassValue[]): string {
  return clsx(inputs);
}

const CCY_LOCALE: Record<string, string> = {
  CNY: "zh-CN", CNH: "zh-CN", USD: "en-US", HKD: "en-HK",
  USDT: "en-US", USDC: "en-US",
};

const CCY_SYMBOL: Record<string, string> = {
  CNY: "¥", CNH: "¥", USD: "$", HKD: "HK$", USDT: "₮", USDC: "$",
};

export function formatAmount(value: number, ccy: string = "CNY", opts: { compact?: boolean; sign?: boolean } = {}): string {
  const locale = CCY_LOCALE[ccy] ?? "en-US";
  const sign = opts.sign && value > 0 ? "+" : "";
  const fixed = 2;
  const num = new Intl.NumberFormat(locale, {
    minimumFractionDigits: fixed,
    maximumFractionDigits: fixed,
  }).format(value);
  return `${sign}${num}`;
}

export function ccySymbol(ccy: string): string {
  return CCY_SYMBOL[ccy] ?? "";
}

export function formatBalance(value: number, ccy: string): { whole: string; decimal: string; symbol: string } {
  const symbol = ccySymbol(ccy);
  const fmt = formatAmount(value, ccy);
  const [whole, decimal = "00"] = fmt.split(".");
  return { whole, decimal, symbol };
}

export function maskMiddle(str: string, headLen = 6, tailLen = 6): string {
  if (str.length <= headLen + tailLen) return str;
  return `${str.slice(0, headLen)}····${str.slice(-tailLen)}`;
}

export function maskCard(num: string): string {
  return num.replace(/^(\d{6})(\d+)(\d{4})$/, (_m, a, mid, c) => `${a}${"·".repeat(mid.length)}${c}`);
}

export function formatDate(d: Date | string, opts: { time?: boolean } = {}): string {
  const dt = typeof d === "string" ? new Date(d) : d;
  const yyyy = dt.getFullYear();
  const mm = String(dt.getMonth() + 1).padStart(2, "0");
  const dd = String(dt.getDate()).padStart(2, "0");
  if (!opts.time) return `${yyyy}-${mm}-${dd}`;
  const hh = String(dt.getHours()).padStart(2, "0");
  const mi = String(dt.getMinutes()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd} ${hh}:${mi}`;
}

export function relativeTime(d: Date | string): string {
  const dt = typeof d === "string" ? new Date(d) : d;
  const ms = Date.now() - dt.getTime();
  const min = Math.floor(ms / 60000);
  if (min < 1) return "刚刚";
  if (min < 60) return `${min} 分钟前`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr} 小时前`;
  const d2 = Math.floor(hr / 24);
  if (d2 < 30) return `${d2} 天前`;
  return formatDate(dt);
}

export function shuffle<T>(arr: T[]): T[] {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function copy(text: string): Promise<void> {
  if (navigator.clipboard?.writeText) return navigator.clipboard.writeText(text);
  return new Promise((resolve) => {
    const ta = document.createElement("textarea");
    ta.value = text; document.body.appendChild(ta); ta.select();
    document.execCommand("copy"); document.body.removeChild(ta); resolve();
  });
}


