      {/* === Recent activity === */}
      <InfoCard
        title="最近交易"
        action={<Link to="/tx" className="text-14 font-semibold text-brand">查看全部</Link>}
      >
        {TRANSACTIONS.slice(0, 3).map((tx) => {
          const inflow = tx.amount > 0;
          const isExchange = tx.type === "exchange";
          return (
            <Link key={tx.id} to={`/tx/${tx.id}`} className="row-tap flex items-center py-2.5">
              <ActivityIcon kind={isExchange ? "swap" : inflow ? "in" : "out"} />
