                <div className="text-15 font-semibold text-ink-900 truncate">{tx.counterparty || tx.id}</div>
                <div className="text-12 text-ink-400 mt-0.5">{tx.date.replace(/-/g, "/")}</div>
              </div>
              <div className={cn(
                "text-15 font-bold num tracking-snug",
                inflow ? "text-success" : "text-ink-900"
