/* ─── Reusable mini-components ──────────────────────────────────────── */

function ActionBtn({ label, icon, primary, onClick }: { label: string; icon: React.ReactNode; primary?: boolean; onClick?: () => void }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        "h-12 rounded-pill flex items-center justify-center gap-1.5 text-14 font-semibold tracking-snug transition-transform duration-120 active:scale-[0.96]",
        primary
          ? "bg-brand text-white shadow-brand"
          : "bg-white text-ink-900 shadow-card"
      )}
    >
      <span className="w-[18px] h-[18px] flex items-center justify-center shrink-0">{icon}</span>
      {label}
    </button>
  );
}

function InfoCard({ title, action, children }: { title: string; action?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section className="mx-4 mb-3 rounded-2xl bg-white shadow-card p-5">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-17 font-extrabold text-brand tracking-snug">{title}</h3>
        {action}
      </div>
      {children}
    </section>
  );
}

function WalletRow({ ccy, hidden }: { ccy: string; hidden: boolean }) {
  const meta = CCY_NAMES[ccy];
  const tone = CCY_TONE[ccy];
  const w = WALLETS.find((x) => x.ccy === ccy);
  if (!w) return null;
  return (
    <Link to={`/account/${ccy}`} className="row-tap flex items-center py-2.5">
      <div className={cn("w-10 h-10 rounded-full flex items-center justify-center font-bold text-15 tracking-tight mr-3.5 shrink-0", tone.bg, tone.fg)}>
        {meta.symbol}
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-15 font-bold text-brand tracking-snug leading-tight">{meta.zh}</div>
        <div className="text-12 text-ink-400 mt-[2px] font-medium">{meta.en}</div>
      </div>
      <div className="text-17 font-bold text-brand num tracking-snug">
        {hidden ? "·····" : fmt(w.balance)}
      </div>
    </Link>
  );
}

function ActivityIcon({ kind }: { kind: "in" | "out" | "swap" }) {
  if (kind === "in") {
    return (
      <div className="w-10 h-10 rounded-full bg-ccyUSD-bg text-success flex items-center justify-center mr-3.5 shrink-0">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><polyline points="19 12 12 19 5 12"/></svg>
      </div>
    );
  }
  if (kind === "out") {
    return (
      <div className="w-10 h-10 rounded-full bg-ink-50 text-ink-900 flex items-center justify-center mr-3.5 shrink-0">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="19" x2="12" y2="5"/><polyline points="5 12 12 5 19 12"/></svg>
      </div>
    );
  }
  return (
    <div className="w-10 h-10 rounded-full bg-ink-50 text-ink-900 flex items-center justify-center mr-3.5 shrink-0">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3l4 4-4 4"/><path d="M21 7H9a4 4 0 00-4 4v2"/><path d="M7 21l-4-4 4-4"/><path d="M3 17h12a4 4 0 004-4v-2"/></svg>
    </div>
  );
}

